+import { writeFile, unlink, stat } from "fs/promises";
+import { join, extname } from "path";
+import { randomUUID } from "crypto";
+
+interface UploadResult {
+  fileId: string;
+  filename: string;
+  size: number;
+  mimeType: string;
+}
+
+var ALLOWED_EXTENSIONS = new Set([".png", ".jpg", ".jpeg", ".gif", ".pdf", ".docx"]);
+var MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
+var UPLOAD_DIR = "/var/data/uploads";
+
+export async function handleFileUpload(
+  fileBuffer: Buffer,
+  originalName: string,
+  mimeType: string
+): Promise<UploadResult> {
+  if (!fileBuffer || fileBuffer.length === 0) {
+    throw new Error("File buffer is empty");
+  }
+
+  if (!originalName || originalName.trim().length === 0) {
+    throw new Error("Original filename is required");
+  }
+
+  var extension = extname(originalName).toLowerCase();
+  if (!ALLOWED_EXTENSIONS.has(extension)) {
+    throw new Error(
+      "File type not allowed: " + extension + ". Accepted: " + Array.from(ALLOWED_EXTENSIONS).join(", ")
+    );
+  }
+
+  if (fileBuffer.length > MAX_FILE_SIZE) {
+    throw new Error(
+      "File exceeds maximum size of " + (MAX_FILE_SIZE / 1024 / 1024) + " MB"
+    );
+  }
+
+  var fileId = randomUUID();
+  var storedName = fileId + extension;
+  var filePath = join(UPLOAD_DIR, storedName);
+
+  try {
+    await writeFile(filePath, fileBuffer);
+
+    var fileStats = await stat(filePath);
+
+    return {
+      fileId: fileId,
+      filename: storedName,
+      size: fileStats.size,
+      mimeType: mimeType,
+    };
+  } catch (err) {
+    try {
+      await unlink(filePath);
+    } catch {
+      // cleanup is best-effort; the file may not have been written
+    }
+
+    throw new Error(
+      "Failed to write file: " + (err instanceof Error ? err.message : "unknown error")
+    );
+  }
+}
